DELETE FROM meal_item
WHERE id = #{id}
AND source_type = 'PERSONAL'
AND owner_user_id = #{userId}

mapper.select:
SELECT 
FROM meal_item
WHERE id = #{id}
AND source_type = 'PERSONAL'
AND owner_user_id = #{userId}

SELECT FROM meal_item
source_type = 'PERSONAL' AND owner_user_id = #{userId}
source_type = 'PUBLIC' AND owner_user_id IS NULL AND review_status = 'APPROVED'
AND (#{mealTimeJson} = '[]' OR JSON_OVERLAPS(meal_time, #{mealTimeJson}) OR (JSON_OVERLAPS(#{mealTimeJson}, JSON_ARRAY('早餐','午餐','晚餐')) AND JSON_CONTAINS(meal_time, JSON_QUOTE('三餐')))) AND (#{moodJson} = '[]' OR JSON_OVERLAPS(mood, #{moodJson})) AND (#{sceneJson} = '[]' OR JSON_OVERLAPS(scene, #{sceneJson})) AND (#{healthGoalJson} = '[]' OR JSON_OVERLAPS(health_goal, #{healthGoalJson})) AND (#{cuisineJson} = '[]' OR JSON_OVERLAPS(cuisine, #{cuisineJson})) AND (#{foodTypeJson} = '[]' OR JSON_OVERLAPS(food_type, #{foodTypeJson})) AND (#{tasteJson} = '[]' OR JSON_OVERLAPS(taste, #{tasteJson})) AND (#{convenienceJson} = '[]' OR JSON_OVERLAPS(convenience, #{convenienceJson}))
ORDER BY updated_at DESC, id DESC LIMIT #{limit}
